25	{"iteration": 13, "system": "unified_confusion_retrieval_memory", "avg_val": 49.6, "axis": "exploitation", "hypothesis": "Replacing the two-phase confusion-slot injection with a single unified ranking that scores each example as jaccard(query, ex) + alpha*log(1+confusion_affinity(ex.label)) will outperform adaptive_tokenizer_confusion_memory, because confusion examples are only surfaced when they are also topically similar to the query, ending the pattern where fixed confusion slots displace more-relevant similarity examples from the context budget.", "delta": -2.6, "outcome": "49.6% (-2.6)", "components": ["unified_scoring", "confusion_affinity_bonus", "log_scaled_bonus", "adaptive_tokenizer", "prediction_normalization", "selection_algorithm_axis"], "timing_s": {"propose": 620.7, "bench": 2596.8, "wall": 3227.8}, "propose_cost_usd": 2.781396, "solver_cost_usd": 0.3486}
